select fc1_0.id,fc1_0.auto_generated,fc1_0.available,fc1_0.away_team_id,fc1_0.elapsed_min,fc1_0.finished,fc1_0.goals_away,fc1_0.goals_home,fc1_0.home_team_id,fc1_0.kickoff,l1_0.id,l1_0.auto_generated,l1_0.available,l1_0.match_collect,l1_0.name,l1_0.uid,fc1_0.league_season_id,mcs1_0.id,mcs1_0.fixture_core_id,mcs1_0.last_collected_at,mcs1_0.match_collect_status,fc1_0.status_code,fc1_0.status_text,fc1_0.uid from fixture_core fc1_0 join league_core l1_0 on l1_0.id=fc1_0.league_id join league_season_core ls1_0 on ls1_0.id=fc1_0.league_season_id left join fixture_match_collect_state mcs1_0 on fc1_0.id=mcs1_0.fixture_core_id where l1_0.uid=? and ls1_0.current=true order by fc1_0.kickoff,fc1_0.id
